import React, { useState } from 'react'
import axiosInstance from '../api/axiosInstance'

function Register() {
    const [name, setName] = useState('')
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [battingStyle, setBattingStyle] = useState('')
    const [bowlingStyle, setBowlingStyle] = useState('')
    const [playingRole, setPlayingRole] = useState('')

    async function handleRegister(e) {
        e.preventDefault()
        const response = await axiosInstance.post('/player/register', { name, email, password, battingStyle, bowlingStyle, playingRole })


    }
    return (
        <div><h1>Register</h1>
            <form onSubmit={handleRegister}>
                <div><label >Name</label><input type="text" onChange={(e)=>{setName(e.target.value)}}  value={name} /></div>
                <div><label >Email</label><input type="text" onChange={(e)=>{setEmail(e.target.value)}} value={email} /></div>
                <div><label >Password</label><input type="text" onChange={(e)=>{setPassword(e.target.value)}} value={password}/></div>
                <div><label >BattingStyle</label>
                <select value={battingStyle} onChange={(e) => setBattingStyle(e.target.value)}>
                    <option value="left-hander">Left-hander</option>
                    <option value="right-hander">Right-hander</option>
                </select></div>
                <div><label >BowlingStyle</label>
                <select value={bowlingStyle} onChange={(e) => setBowlingStyle(e.target.value)}>
                    <option value="left-arm-pace">Left-arm-pace</option>
                <option value="right-arm-pace">Right-arm-pace</option>
                <option value="right-arm-spin">Right-arm-spin</option>
                <option value="left-arm-spin">Left-arm-spin</option>
                </select></div>
                <div><label >PlayerRole</label><select onChange={(e)=>setPlayingRole(e.target.value)}value={playingRole} >
                    <option value="batsman">Batsman</option>
                    <option value="wk-batsman">WK-Batsman</option>
                    <option value="bowler">Bowler</option>
                    <option value="all-rounder">All-rounder</option>
                </select></div>
        <button>Register</button>

            </form>
        </div>

    )
}

export default Register
